void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // 修正后的坐标系处理
    vec2 uv = fragCoord / iResolution.xy * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y; // 保持宽高比

    // 极光噪声层
    vec3 auroraPos = vec3(uv * 3.0, iTime * 0.3);
    float noise = 0.5 * sin(auroraPos.x*5.0 + auroraPos.z) 
                + 0.3 * sin(auroraPos.y*3.0 + auroraPos.z);
    noise += 0.2 * sin(auroraPos.x*10.0 + auroraPos.z) 
                  * sin(auroraPos.y*8.0 + auroraPos.z);

    // 极光形状遮罩
    float mask = smoothstep(0.3, 1.2, 1.0 - length(uv + vec2(0.0, 0.3)));
    float aurora = noise * mask * 2.0;

    // 颜色渐变处理
    vec3 color = mix(vec3(0.1, 0.4, 0.6), 
                    vec3(0.3, 0.9, 0.7), 
                    smoothstep(0.3, 0.9, aurora));

    color = mix(color, 
               vec3(0.7, 0.3, 0.9), 
               smoothstep(0.5, 1.0, aurora));

    // 动态流动效果
    float flow = sin(uv.x*8.0 + iTime*3.0) * 0.1;
    uv.y += flow * smoothstep(0.5, 1.0, aurora);

    // 次级极光层
    float aurora2 = sin(uv.x*12.0 + uv.y*25.0 + iTime*2.5)*0.5 
                  + sin(uv.x*18.0 + uv.y*12.0 + iTime*2.0)*0.3;
    color += vec3(0.4, 0.8, 1.0) * aurora2 * 0.2;

    // 程序化星空（无需纹理）
    vec2 starUV = fragCoord / iResolution.xy;
    float stars = pow(fract(sin(dot(starUV, vec2(12.9898,78.233))) * 43758.5453), 50.0);
    color = mix(color, vec3(1.0), stars * 0.5);

    // 底部渐隐
    color *= smoothstep(-0.5, 0.2, uv.y);

    // 辉光效果
    color += vec3(0.4, 0.7, 0.9) * pow(aurora, 3.0) * 0.4;

    fragColor = vec4(color, 1.0);
}
